def count_lowercase_letters(s):
    letter_count = {chr(i): 0 for i in range(97, 123)}  # Initialize dictionary for a-z
    for char in s:
        if char in string.ascii_lowercase:  # Check if the character is a lowercase letter
            letter_count[char] += 1
    return letter_count
